fn d_is_miss(dentry: *const dentry) -> bool {
__d_entry_type(dentry) == 0
}

fn d_can_lookup(dentry: *const dentry) -> bool {
__d_entry_type(dentry) == 1048576
}

fn d_is_autodir(dentry: *const dentry) -> bool {
__d_entry_type(dentry) == 1572864
}

