fn lsm_get_xattr_slot(xattrs: *mut xattr, __v0: *mut i32) -> *mut xattr {
if unlikely!(xattrs.is_null()) != 0 {
return core::ptr::null_mut::<xattr>();
}
let __v1: i32 = unsafe { *__v0 };
unsafe {
*__v0 = __v1.wrapping_add(1);
}
xattrs.wrapping_offset(__v1 as isize)
}

